import Foundation
import UIKit

/// Exact local store artwork for the News dashboard. The PNG data is embedded
/// directly because loose PNG resources are not reliably resolved by SwiftUI's
/// Image(name:) when they are outside a compiled .xcassets catalog.
/// Decoded once; no network, shaders or Core Animation effects.
enum BloomBoxNewsBrandIcons {
    private static func decodePNG(_ value: String) -> UIImage? {
        guard let data = Data(base64Encoded: value, options: .ignoreUnknownCharacters),
              data.starts(with: [0x89, 0x50, 0x4E, 0x47]) else { return nil }
        return UIImage(data: data)
    }

    static let googlePlay: UIImage? = decodePNG(googlePlayBase64)
    static let appleAppStore: UIImage? = decodePNG(appleAppStoreBase64)

